    10	
    11	// gitCmd creates a git command with LC_ALL=C to ensure English output for parsing.
    12	func gitCmd(args ...string) *exec.Cmd {
    13		cmd := exec.Command("git", args...)
    14		cmd.Env = append(os.Environ(), "LC_ALL=C")
    15		return cmd
    16	}
    17	
    18	// Run executes a git command and returns its trimmed stdout.
    19	// If the command fails, the error includes stderr.
    20	func Run(args ...string) (string, error) {
    21		return RunIn("", args...)
    22	}
    23	
    24	// RunIn executes a git command in a specific directory and returns its trimmed stdout.
    25	func RunIn(dir string, args ...string) (string, error) {
    26		out, err := runRawIn(dir, args...)
    27		return strings.TrimSpace(out), err
    28	}
    29	
    30	// runRawIn is RunIn without trimming. Porcelain output needs this: its first
    31	// line can start with a space (" M file").
    32	func runRawIn(dir string, args ...string) (string, error) {
    33		cmd := gitCmd(args...)
    34		if dir != "" {
    35			cmd.Dir = dir
    36		}
    37	
    38		var stdout, stderr bytes.Buffer
    39		cmd.Stdout = &stdout
    40		cmd.Stderr = &stderr
    41	
    42		if err := cmd.Run(); err != nil {
    43			errMsg := strings.TrimSpace(stderr.String())
    44			if errMsg == "" {
    45				errMsg = err.Error()
    46			}
    47			return "", fmt.Errorf("git %s: %s", strings.Join(args, " "), errMsg)
    48		}
    49	
    50		return stdout.String(), nil
    51	}
    52	
    53	// RunPassthrough executes a git command with stdout/stderr connected to the terminal.
    54	// Used for commands where the user needs to see real-time output (rebase, push, etc.).
    55	func RunPassthrough(args ...string) error {
    56		return RunPassthroughIn("", args...)
    57	}
    58	
    59	// RunPassthroughIn executes a git command in a directory with passthrough I/O.
    60	func RunPassthroughIn(dir string, args ...string) error {
    61		cmd := gitCmd(args...)
    62		if dir != "" {
    63			cmd.Dir = dir
    64		}
    65		cmd.Stdin = os.Stdin
    66		cmd.Stdout = os.Stdout
    67		cmd.Stderr = os.Stderr
    68		return cmd.Run()
    69	}
    70	
    71	// runQuiet runs cmd with stdin and stdout on the terminal, but drops git's
    72	// "hint:" lines and the "Could not apply <sha>... # <subject>" echo from
    73	// stderr. wt prints its own guidance, and "error: could not apply" stays.
    74	func runQuiet(cmd *exec.Cmd) error {
    75		var stderr bytes.Buffer
    76		cmd.Stdin = os.Stdin
    77		cmd.Stdout = os.Stdout
    78		cmd.Stderr = &stderr
    79		err := cmd.Run()
    80		fmt.Fprint(os.Stderr, filterGitNoise(stderr.String()))
    81		return err
    82	}
    83	
    84	func filterGitNoise(s string) string {
    85		var b strings.Builder
    86		for line := range strings.SplitAfterSeq(s, "\n") {
    87			// Drop "Rebasing (1/2)\r" progress; on a terminal \r would have erased it.
    88			if i := strings.LastIndex(line, "\r"); i >= 0 {
    89				line = line[i+1:]
    90			}
    91			if strings.HasPrefix(line, "hint:") || strings.HasPrefix(line, "Could not apply ") {
    92				continue
    93			}
    94			b.WriteString(line)
    95		}
    96		return b.String()
    97	}
    98	
    99	// RunSilent executes a git command and discards all output.
   100	// Returns only whether it succeeded.
   101	func RunSilent(args ...string) error {
   102		cmd := gitCmd(args...)
   103		cmd.Stdout = nil
   104		cmd.Stderr = nil
   105		return cmd.Run()
   106	}
   107	
   108	// RunSilentIn executes a git command in a directory silently.
   109	func RunSilentIn(dir string, args ...string) error {
   110		cmd := gitCmd(args...)
   111		if dir != "" {
   112			cmd.Dir = dir
   113		}
   114		cmd.Stdout = nil
   115		cmd.Stderr = nil
   116		return cmd.Run()
   117	}
