     9	
    10	// Worktree represents a git worktree entry.
    11	type Worktree struct {
    12		Path   string
    13		Branch string
    14	}
    15	
    16	// ListWorktrees returns all worktrees from `git worktree list --porcelain`.
    17	func ListWorktrees() ([]Worktree, error) {
    18		out, err := Run("worktree", "list", "--porcelain")
    19		if err != nil {
    20			return nil, err
    21		}
    22		return ParseWorktreeList(out), nil
    23	}
    24	
    25	// ParseWorktreeList parses the porcelain output of `git worktree list`.
    26	func ParseWorktreeList(out string) []Worktree {
    27		var worktrees []Worktree
    28		var current Worktree
    29	
    30		for line := range strings.SplitSeq(out, "\n") {
    31			switch {
    32			case strings.HasPrefix(line, "worktree "):
    33				current = Worktree{Path: strings.TrimPrefix(line, "worktree ")}
    34			case strings.HasPrefix(line, "branch "):
    35				ref := strings.TrimPrefix(line, "branch ")
    36				// "refs/heads/feature" → "feature"
    37				current.Branch = strings.TrimPrefix(ref, "refs/heads/")
    38			case line == "":
    39				if current.Path != "" {
    40					worktrees = append(worktrees, current)
    41					current = Worktree{}
    42				}
    43			}
    44		}
    45		// Last entry (porcelain output may not end with blank line)
    46		if current.Path != "" {
    47			worktrees = append(worktrees, current)
    48		}
    49	
    50		return worktrees
    51	}
    52	
    53	// MainWorktree returns the path of the main (first) worktree.
    54	func MainWorktree() (string, error) {
    55		wts, err := ListWorktrees()
    56		if err != nil {
    57			return "", err
    58		}
    59		if len(wts) == 0 {
    60			return "", fmt.Errorf("no worktrees found (not a git repository?)")
    61		}
    62		return wts[0].Path, nil
    63	}
    64	
    65	// ParentDir returns the parent directory of the main worktree
    66	// (where sibling worktrees are created).
    67	func ParentDir() (string, error) {
    68		main, err := MainWorktree()
    69		if err != nil {
    70			return "", err
    71		}
    72		return filepath.Dir(main), nil
    73	}
    74	
    75	// AddWorktree creates a new worktree with a new branch from a base ref.
    76	func AddWorktree(path, branch, baseRef string) error {
    77		if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
    78			return err
    79		}
    80		_, err := Run("worktree", "add", "-b", branch, path, baseRef)
    81		return err
    82	}
    83	
    84	// AddWorktreeFromExisting creates a worktree checking out an existing branch.
    85	func AddWorktreeFromExisting(path, branch string) error {
    86		if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
    87			return err
    88		}
    89		_, err := Run("worktree", "add", path, branch)
    90		return err
    91	}
    92	
    93	// AddWorktreeFromRemote creates a worktree with a local tracking branch from a remote.
    94	func AddWorktreeFromRemote(path, localBranch, remoteBranch string) error {
    95		if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
    96			return err
    97		}
    98		_, err := Run("worktree", "add", "-b", localBranch, path, remoteBranch)
    99		return err
   100	}
   101	
   102	// RemoveWorktree removes a worktree (force).
   103	// After removal, cleans up the parent directory if it's empty.
   104	func RemoveWorktree(path string) error {
   105		_, err := Run("worktree", "remove", path, "--force")
   106		if err != nil {
   107			return err
   108		}
   109		// Clean up empty parent dir (e.g. wt-repo/ after last worktree removed).
   110		// os.Remove only succeeds on empty directories, so this is safe.
   111		_ = os.Remove(filepath.Dir(path))
   112		return nil
   113	}
   114	
   115	// MoveWorktree moves a worktree to a new path.
   116	func MoveWorktree(oldPath, newPath string) error {
   117		if err := os.MkdirAll(filepath.Dir(newPath), 0755); err != nil {
   118			return err
   119		}
   120		_, err := Run("worktree", "move", oldPath, newPath)
   121		return err
   122	}
   123	
   124	// PruneWorktrees cleans up stale worktree bookkeeping.
   125	func PruneWorktrees() {
   126		_ = RunSilent("worktree", "prune")
   127	}
