    12	
    13	// CurrentBranch returns the current branch name, or "" for detached HEAD.
    14	func CurrentBranch() (string, error) {
    15		return Run("rev-parse", "--abbrev-ref", "HEAD")
    16	}
    17	
    18	// CurrentBranchIn returns the current branch for a specific worktree.
    19	func CurrentBranchIn(dir string) (string, error) {
    20		return RunIn(dir, "rev-parse", "--abbrev-ref", "HEAD")
    21	}
    22	
    23	// BranchExists checks if a local branch exists.
    24	func BranchExists(name string) bool {
    25		return RunSilent("show-ref", "--verify", "--quiet", "refs/heads/"+name) == nil
    26	}
    27	
    28	// IsValidBranchName reports whether git accepts name as a new branch name.
    29	func IsValidBranchName(name string) bool {
    30		return !strings.HasPrefix(name, "-") && RunSilent("check-ref-format", "--branch", name) == nil
    31	}
    32	
    33	// MergedBranches returns the local branches whose tips are reachable from ref.
    34	func MergedBranches(ref string) (map[string]bool, error) {
    35		out, err := Run("branch", "--merged", ref, "--format=%(refname:short)")
    36		if err != nil {
    37			return nil, err
    38		}
    39		merged := make(map[string]bool)
    40		for b := range strings.FieldsSeq(out) {
    41			merged[b] = true
    42		}
    43		return merged, nil
    44	}
    45	
    46	// BranchMoved reports whether a branch's reflog shows any change since it was
    47	// created. A fresh branch also counts as merged into its base, so callers use
    48	// this to tell the two apart.
    49	func BranchMoved(branch string) bool {
    50		out, err := Run("reflog", "show", "--format=%H", "refs/heads/"+branch, "--")
    51		return err == nil && strings.Contains(out, "\n")
    52	}
    53	
    54	// RemoteBranchExists checks if a remote branch exists (e.g., "origin/feature").
    55	func RemoteBranchExists(name string) bool {
    56		return RunSilent("show-ref", "--verify", "--quiet", "refs/remotes/"+name) == nil
    57	}
    58	
    59	// ResolveBranch tries to find a branch ref in order: local, remotes/<name>, remotes/origin/<name>.
    60	// Returns the ref, whether it's remote, and any error.
    61	func ResolveBranch(name, remote string) (ref string, isRemote bool, err error) {
    62		// Local branch
    63		if BranchExists(name) {
    64			return name, false, nil
    65		}
    66		// Remote with explicit prefix (e.g., "origin/branch")
    67		if RemoteBranchExists(name) {
    68			return name, true, nil
    69		}
    70		// Remote without prefix
    71		fullRemote := remote + "/" + name
    72		if RemoteBranchExists(fullRemote) {
    73			return fullRemote, true, nil
    74		}
    75		return "", false, fmt.Errorf("branch not found: %s (tried local and remote refs)", name)
    76	}
    77	
    78	// RenameBranch renames a local branch.
    79	func RenameBranch(oldName, newName string) error {
    80		_, err := Run("branch", "-m", oldName, newName)
    81		return err
    82	}
    83	
    84	// DeleteBranch force-deletes a local branch.
    85	func DeleteBranch(name string) error {
    86		_, err := Run("branch", "-D", name)
    87		return err
    88	}
    89	
    90	// DeleteRemoteBranch deletes a branch on the remote.
    91	func DeleteRemoteBranch(remote, branch string) error {
    92		_, err := Run("push", remote, "--delete", branch)
    93		return err
    94	}
    95	
    96	// AheadBehind returns how many commits a branch is ahead/behind a ref.
    97	type AheadBehind struct {
    98		Ahead  int
    99		Behind int
   100	}
   101	
   102	// GetAheadBehind computes ahead/behind between HEAD and a remote ref.
   103	func GetAheadBehind(remoteRef string) (AheadBehind, error) {
   104		return GetAheadBehindIn("", remoteRef)
   105	}
   106	
   107	// GetAheadBehindIn computes ahead/behind for a specific worktree.
   108	func GetAheadBehindIn(dir, remoteRef string) (AheadBehind, error) {
   109		ab := AheadBehind{}
   110	
   111		behind, err := RunIn(dir, "rev-list", "--count", "HEAD.."+remoteRef)
   112		if err != nil {
   113			return ab, err
   114		}
   115		ab.Behind, err = strconv.Atoi(strings.TrimSpace(behind))
   116		if err != nil {
   117			return ab, fmt.Errorf("invalid behind count %q: %w", behind, err)
   118		}
   119	
   120		ahead, err := RunIn(dir, "rev-list", "--count", remoteRef+"..HEAD")
   121		if err != nil {
   122			return ab, err
   123		}
   124		ab.Ahead, err = strconv.Atoi(strings.TrimSpace(ahead))
   125		if err != nil {
   126			return ab, fmt.Errorf("invalid ahead count %q: %w", ahead, err)
   127		}
   128	
   129		return ab, nil
   130	}
   131	
   132	// Upstream returns the upstream tracking branch, or "" if none.
   133	func Upstream() string {
   134		out, err := Run("rev-parse", "--abbrev-ref", "@{upstream}")
   135		if err != nil {
   136			return ""
   137		}
   138		return out
   139	}
   140	
   141	// LastCommitAge returns a short relative age (e.g. "2h", "3d") of the commit
   142	// checked out in the worktree, or "" if it can't be read.
   143	func LastCommitAge(dir string) string {
   144		t, ok := lastCommitTime(dir)
   145		if !ok {
   146			return ""
   147		}
   148		return formatRelativeAge(time.Since(t))
   149	}
   150	
   151	// WorktreeAgeDays returns the number of days since the most recent activity
   152	// in the worktree, or -1 if it can't be determined. Used for staleness checks.
   153	func WorktreeAgeDays(dir string) int {
   154		t, ok := worktreeActivity(dir)
   155		if !ok {
   156			return -1
   157		}
   158		return int(time.Since(t).Hours() / 24)
   159	}
   160	
   161	// worktreeActivity returns the most recent of (worktree creation, last commit).
   162	// Using max(...) keeps brand-new worktrees from looking stale because their
   163	// base branch's tip is old.
   164	func worktreeActivity(dir string) (time.Time, bool) {
   165		created, hasCreated := worktreeCreationTime(dir)
   166		committed, hasCommit := lastCommitTime(dir)
   167		switch {
   168		case hasCreated && hasCommit:
   169			if created.After(committed) {
   170				return created, true
   171			}
   172			return committed, true
   173		case hasCreated:
   174			return created, true
   175		case hasCommit:
   176			return committed, true
   177		}
   178		return time.Time{}, false
   179	}
   180	
   181	// worktreeCreationTime parses the first reflog entry for HEAD in the given
   182	// worktree. Returns (zero, false) if the reflog is missing (e.g.
   183	// core.logAllRefUpdates=false) or has been pruned by gc.
   184	func worktreeCreationTime(dir string) (time.Time, bool) {
   185		pathOut, err := RunIn(dir, "rev-parse", "--git-path", "logs/HEAD")
   186		if err != nil {
   187			return time.Time{}, false
   188		}
   189		logPath := strings.TrimSpace(pathOut)
   190		if !filepath.IsAbs(logPath) {
   191			logPath = filepath.Join(dir, logPath)
   192		}
   193	
   194		f, err := os.Open(logPath)
   195		if err != nil {
   196			return time.Time{}, false
   197		}
   198		defer func() { _ = f.Close() }()
   199	
   200		scanner := bufio.NewScanner(f)
   201		if !scanner.Scan() {
   202			return time.Time{}, false
   203		}
   204		return parseReflogTime(scanner.Text())
   205	}
   206	
   207	// parseReflogTime extracts the unix timestamp from a reflog line of the form:
   208	//
   209	//	<old-sha> <new-sha> <name> <email> <unix-ts> <tz>[\t<reason>]
   210	//
   211	// The timestamp is the second-to-last whitespace field before the optional
   212	// tab-separated reason.
   213	func parseReflogTime(line string) (time.Time, bool) {
   214		if tab := strings.IndexByte(line, '\t'); tab >= 0 {
   215			line = line[:tab]
   216		}
   217		fields := strings.Fields(line)
   218		if len(fields) < 2 {
   219			return time.Time{}, false
   220		}
   221		ts, err := strconv.ParseInt(fields[len(fields)-2], 10, 64)
   222		if err != nil {
   223			return time.Time{}, false
   224		}
   225		return time.Unix(ts, 0), true
   226	}
   227	
   228	// lastCommitTime returns the committer timestamp of HEAD in the given worktree.
   229	func lastCommitTime(dir string) (time.Time, bool) {
   230		out, err := RunIn(dir, "log", "-1", "--format=%ct")
   231		if err != nil {
   232			return time.Time{}, false
   233		}
   234		ts, err := strconv.ParseInt(strings.TrimSpace(out), 10, 64)
   235		if err != nil {
   236			return time.Time{}, false
   237		}
   238		return time.Unix(ts, 0), true
   239	}
   240	
   241	// formatRelativeAge formats a duration as a short relative age string,
   242	// roughly matching git's --date=relative thresholds: s, m, h, d, w, mo, y.
   243	func formatRelativeAge(d time.Duration) string {
   244		if d < 0 {
   245			d = 0
   246		}
   247		switch {
   248		case d < time.Minute:
   249			return fmt.Sprintf("%ds", int(d.Seconds()))
   250		case d < time.Hour:
   251			return fmt.Sprintf("%dm", int(d.Minutes()))
   252		case d < 24*time.Hour:
   253			return fmt.Sprintf("%dh", int(d.Hours()))
   254		}
   255		days := int(d.Hours() / 24)
   256		switch {
   257		case days < 14:
   258			return fmt.Sprintf("%dd", days)
   259		case days < 70:
   260			return fmt.Sprintf("%dw", days/7)
   261		case days < 365:
   262			return fmt.Sprintf("%dmo", days/30)
   263		}
   264		return fmt.Sprintf("%dy", days/365)
   265	}
