     8	
     9	// RepoName returns the basename of the main worktree (the true repo name).
    10	// Uses MainWorktree() rather than --show-toplevel, which would return the
    11	// linked worktree's directory name when called from inside one.
    12	func RepoName() (string, error) {
    13		main, err := MainWorktree()
    14		if err != nil {
    15			return "", err
    16		}
    17		return filepath.Base(main), nil
    18	}
    19	
    20	// TopLevel returns the absolute path to the repository root.
    21	func TopLevel() (string, error) {
    22		return Run("rev-parse", "--show-toplevel")
    23	}
    24	
    25	// GitDir returns the .git directory path (handles worktrees where .git is a file).
    26	func GitDir() (string, error) {
    27		return Run("rev-parse", "--git-dir")
    28	}
    29	
    30	// Username returns the git user's first name, lowercased.
    31	// e.g., "Michael Williams" → "michael"
    32	func Username() (string, error) {
    33		name, err := Run("config", "user.name")
    34		if err != nil {
    35			return "", err
    36		}
    37		name = strings.ToLower(name)
    38		name = strings.ReplaceAll(name, " ", "-")
    39		parts := strings.SplitN(name, "-", 2)
    40		return parts[0], nil
    41	}
    42	
    43	// IsInsideWorkTree returns true if the current directory is inside a git repo.
    44	func IsInsideWorkTree() bool {
    45		err := RunSilent("rev-parse", "--is-inside-work-tree")
    46		return err == nil
    47	}
    48	
    49	// IsInsideRepo returns true if the current directory is inside a git
    50	// repository, bare or not.
    51	func IsInsideRepo() bool {
    52		return RunSilent("rev-parse", "--git-dir") == nil
    53	}
    54	
    55	// IsBareRepo returns true if the current directory is inside a bare repository.
    56	func IsBareRepo() bool {
    57		out, err := Run("rev-parse", "--is-bare-repository")
    58		return err == nil && out == "true"
    59	}
    60	
    61	// Fetch fetches a specific ref from a remote.
    62	func Fetch(remote string, refs ...string) error {
    63		args := append([]string{"fetch", remote}, refs...)
    64		return RunSilent(args...)
    65	}
    66	
    67	// FetchAll fetches all refs from a remote.
    68	func FetchAll(remote string) error {
    69		return RunSilent("fetch", remote)
    70	}
    71	
    72	// isDir returns true if the path exists and is a directory.
    73	func isDir(path string) bool {
    74		info, err := os.Stat(path)
    75		return err == nil && info.IsDir()
    76	}
    77	
    78	// fileExists returns true if the path exists.
    79	func fileExists(path string) bool {
    80		_, err := os.Stat(path)
    81		return err == nil
    82	}

