 34	// runGH executes a gh command and returns stdout.
 35	func runGH(args ...string) (string, error) {
 36		cmd := exec.Command("gh", args...)
 37		var stdout, stderr bytes.Buffer
 38		cmd.Stdout = &stdout
 39		cmd.Stderr = &stderr
 40		if err := cmd.Run(); err != nil {
 41			// Name only the subcommand ("gh pr list"); the full flag list buries the reason.
 42			return "", fmt.Errorf("gh %s: %s", strings.Join(args[:min(2, len(args))], " "), strings.TrimSpace(stderr.String()))
 43		}
 44		return strings.TrimSpace(stdout.String()), nil
 45	}
