 77	// Checks is a PR's statusCheckRollup. gh mixes check runs (which have a name)
 78	// with commit statuses such as codecov (which have a context), and lists a job
 79	// once per workflow event. Decoding gives every check a name and keeps one
 80	// entry per name, the worst result winning.
 81	type Checks []StatusCheckRun
 82	
 83	// UnmarshalJSON implements json.Unmarshaler.
 84	func (cs *Checks) UnmarshalJSON(data []byte) error {
 85		var raw []struct {
 86			StatusCheckRun
 87			Context string `json:"context"`
 88		}
 89		if err := json.Unmarshal(data, &raw); err != nil {
 90			return err
 91		}
 92		rank := map[string]int{"pass": 0, "pending": 1, "fail": 2}
 93		index := map[string]int{}
 94		out := Checks{}
 95		for _, r := range raw {
 96			c := r.StatusCheckRun
 97			if c.Name == "" {
 98				c.Name = r.Context
 99			}
100			if c.Name == "" {
101				continue
102			}
103			if i, ok := index[c.Name]; ok {
104				if rank[c.Result()] > rank[out[i].Result()] {
105					out[i] = c
106				}
107				continue
108			}
109			index[c.Name] = len(out)
110			out = append(out, c)
111		}
112		*cs = out
113		return nil
114	}
