116	// Result classifies a CI check as "pass", "fail", or "pending".
117	func (c StatusCheckRun) Result() string {
118		switch {
119		case c.Conclusion == "SUCCESS" || c.Conclusion == "SKIPPED" || c.State == "SUCCESS":
120			return "pass"
121		case c.Conclusion == "FAILURE" || c.Conclusion == "TIMED_OUT" || c.Conclusion == "CANCELLED" || c.State == "FAILURE" || c.State == "ERROR":
122			return "fail"
123		default:
124			return "pending"
125		}
126	}
