153	// getReviewSummary computes review state counts from requests and reviews.
154	// A pending re-review request supersedes a stale completed review.
155	func getReviewSummary(requests []ReviewRequest, reviews []Review) ReviewSummary {
156		reRequested := make(map[string]bool)
157		for _, rr := range requests {
158			if rr.Login != "" {
159				reRequested[rr.Login] = true
160			}
161		}
162	
163		var s ReviewSummary
164		seen := make(map[string]bool)
165		for _, r := range reviews {
166			login := r.Author.Login
167			if login == "" || r.State == "COMMENTED" {
168				continue
169			}
170			seen[login] = true
171			if reRequested[login] {
172				s.Pending++
173				continue
174			}
175			switch r.State {
176			case "APPROVED":
177				s.Approved++
178			case "CHANGES_REQUESTED":
179				s.Changes++
180			}
181		}
182		for _, rr := range requests {
183			if rr.Login != "" && !seen[rr.Login] {
184				seen[rr.Login] = true
185				s.Pending++
186			}
187		}
188		return s
189	}
190	
191	// getCISummary computes CI check state counts from status checks.
192	// Checks with empty names (GitHub summary checks) are excluded.
193	func getCISummary(checks []StatusCheckRun) CISummary {
194		var s CISummary
195		for _, c := range checks {
196			if c.Name == "" {
197				continue
198			}
199			s.Total++
200			switch c.Result() {
201			case "pass":
202				s.Pass++
203			case "fail":
204				s.Fail++
205			default:
206				s.Pending++
207			}
208		}
209		return s
210	}
