212	// ListPRs fetches PRs in a given state with full review/CI data.
213	// When heads are given, it fetches only PRs whose head branch matches one of
214	// them, which is far faster on busy repos than listing the latest 50.
215	func ListPRs(state string, heads ...string) ([]PR, error) {
216		if !IsAvailable() {
217			return nil, nil
218		}
219	
220		fields := "number,headRefName"
221		if state == "open" {
222			fields = "number,headRefName,reviewRequests,latestReviews,statusCheckRollup"
223		}
224		args := []string{"pr", "list", "--state", state, "--json", fields}
225	
226		if len(heads) == 0 {
227			return listPRs(append(args, "--limit", "50")...)
228		}
229		var all []PR
230		for _, q := range headQueries(heads) {
231			// shortcut: head: is a prefix match on GitHub, so a short branch name can
232			// pull in extra PRs and crowd out the limit; callers match exactly.
233			prs, err := listPRs(append(args, "--limit", "100", "--search", q)...)
234			if err != nil {
235				return nil, err
236			}
237			all = append(all, prs...)
238		}
239		return all, nil
240	}
