242	func listPRs(args ...string) ([]PR, error) {
243		out, err := runGH(args...)
244		if err != nil {
245			return nil, err
246		}
247		var prs []PR
248		if err := json.Unmarshal([]byte(out), &prs); err != nil {
249			return nil, err
250		}
251		return prs, nil
252	}
