254	// maxHeadQuery keeps each search under GitHub's 256-character query limit,
255	// with room for the repo and state qualifiers gh adds.
256	const maxHeadQuery = 180
257	
258	// headQueries packs "head:<branch>" terms, which GitHub ORs together, into
259	// search strings no longer than maxHeadQuery.
260	func headQueries(heads []string) []string {
261		var queries []string
262		cur := ""
263		for _, h := range heads {
264			term := "head:" + h
265			if cur != "" && len(cur)+1+len(term) > maxHeadQuery {
266				queries = append(queries, cur)
267				cur = ""
268			}
269			if cur != "" {
270				cur += " "
271			}
272			cur += term
273		}
274		if cur != "" {
275			queries = append(queries, cur)
276		}
277		return queries
278	}
