474	// ReviewItems merges LatestReviews and ReviewRequests into a unified list.
475	// A pending re-review request supersedes any previous completed review
476	// (the old approval is stale after new commits are pushed).
477	func (ws *WatchStatus) ReviewItems() []ReviewItem {
478		// Build set of logins with pending re-review requests
479		reRequested := make(map[string]bool)
480		for _, rr := range ws.ReviewRequests {
481			if rr.Login != "" {
482				reRequested[rr.Login] = true
483			}
484		}
485	
486		seen := make(map[string]bool)
487		var items []ReviewItem
488	
489		for _, r := range ws.LatestReviews {
490			if r.State == "COMMENTED" {
491				continue
492			}
493			login := r.Author.Login
494			if login == "" {
495				continue
496			}
497			seen[login] = true
498	
499			// Re-review request supersedes the stale completed review
500			if reRequested[login] {
501				items = append(items, ReviewItem{Login: login, State: "pending"})
502				continue
503			}
504	
505			state := "approved"
506			if r.State == "CHANGES_REQUESTED" {
507				state = "changes_requested"
508			}
509			items = append(items, ReviewItem{Login: login, State: state})
510		}
511	
512		// Add reviewers who were requested but haven't reviewed yet
513		for _, rr := range ws.ReviewRequests {
514			if rr.Login != "" && !seen[rr.Login] {
515				seen[rr.Login] = true
516				items = append(items, ReviewItem{Login: rr.Login, State: "pending"})
517			}
518		}
519		return items
520	}
