   296	// runCommandIn runs command with sh -c inside dir, attached to the terminal.
   297	// It returns an exitCode error when the command fails, so wt exits with the
   298	// same code.
   299	func runCommandIn(dir, command string) error {
   300		c := exec.Command("sh", "-c", command)
   301		c.Dir = dir
   302		c.Stdin, c.Stdout, c.Stderr = os.Stdin, os.Stdout, os.Stderr
   303	
   304		// Ctrl-C belongs to the command. Catching it here keeps wt alive until
   305		// the command exits; the command still gets the signal.
   306		sig := make(chan os.Signal, 1)
   307		signal.Notify(sig, os.Interrupt)
   308		defer signal.Stop(sig)
   309	
   310		err := c.Run()
   311		var exitErr *exec.ExitError
   312		if errors.As(err, &exitErr) {
   313			return exitCode(max(exitErr.ExitCode(), 1))
   314		}
   315		return err
   316	}
