   223	func detectInit(mainWorktree string) (copyFiles []string, commands []string) {
   224		// Detect .env files
   225		envFiles := []string{".env", ".env.local", ".env.development", ".env.test"}
   226		for _, f := range envFiles {
   227			if fileExists(filepath.Join(mainWorktree, f)) {
   228				copyFiles = append(copyFiles, f)
   229			}
   230		}
   231	
   232		// Detect AI config files/directories
   233		aiConfigs := []string{".claude", ".cursorrules", ".cursor/rules"}
   234		for _, f := range aiConfigs {
   235			if fileExists(filepath.Join(mainWorktree, f)) {
   236				copyFiles = append(copyFiles, f)
   237			}
