   239	
   240		// Detect package manager from lockfile
   241		var execRunner string
   242		for _, lf := range knownLockfiles {
   243			if fileExists(filepath.Join(mainWorktree, lf.file)) {
   244				commands = append(commands, lf.command)
   245				execRunner = lf.exec
   246				break
   247			}
   248		}
