221	// detectInit auto-detects initialization steps from the main worktree.
222	// Returns env files to copy and install commands to run.
223	func detectInit(mainWorktree string) (copyFiles []string, commands []string) {
224		// Detect .env files
225		envFiles := []string{".env", ".env.local", ".env.development", ".env.test"}
226		for _, f := range envFiles {
227			if fileExists(filepath.Join(mainWorktree, f)) {
228				copyFiles = append(copyFiles, f)
229			}
230		}
231	
232		// Detect AI config files/directories
233		aiConfigs := []string{".claude", ".cursorrules", ".cursor/rules"}
234		for _, f := range aiConfigs {
235			if fileExists(filepath.Join(mainWorktree, f)) {
236				copyFiles = append(copyFiles, f)
237			}
238		}
239	
240		// Detect package manager from lockfile
241		var execRunner string
242		for _, lf := range knownLockfiles {
243			if fileExists(filepath.Join(mainWorktree, lf.file)) {
244				commands = append(commands, lf.command)
245				execRunner = lf.exec
246				break
247			}
248		}
249	
250		// Detect Prisma schema anywhere in the repo (requires a JS package manager)
251		if execRunner != "" {
252			if schemaPath := findPrismaSchema(mainWorktree); schemaPath != "" {
253				commands = append(commands, execRunner+" prisma generate --schema "+shellQuoteInit(schemaPath))
254			}
255		}
256	
257		return
258	}
