244	func rebaseContinue(ctx *cmdContext) error {
245		if !git.StateFileExists(stateFileName) {
246			return fmt.Errorf("no rebase in progress\n   Start one with: wt rebase")
247		}
248	
249		didStash, preRef := parseRebaseState()
250	
251		inProgress, _ := git.IsRebaseInProgress()
252		if !inProgress {
253			// The rebase ended outside wt (e.g. plain `git rebase --continue`).
254			// Don't pop a stash this old: the stack may have changed since.
255			git.RemoveStateFile(stateFileName)
256			if didStash {
257				ui.Warn("wt stashed your changes before that rebase. Check `git stash list` for \"wt rebase: auto-stash\".")
258			}
259			return fmt.Errorf("no rebase in progress\n   Start one with: wt rebase")
260		}
261	
262		fmt.Println("Continuing rebase…")
263		if err := git.RebaseContinue(); err != nil {
264			fmt.Println()
265			ui.Warn("Still have conflicts. Resolve them and run:")
266			fmt.Printf("  %s\n", ui.Cyan("wt rebase --continue"))
267			return errSilent
268		}
269		restoreStash(didStash)
270		git.RemoveStateFile(stateFileName)
271	
272		if preRef != "" {
273			autoInstallIfNeeded(ctx, preRef)
274		}
275	
276		fmt.Println()
277		ui.Success("Synced with base branch")
278		return nil
279	}
280	
281	func rebaseAbort() error {
282		inProgress, _ := git.IsRebaseInProgress()
283		hasState := git.StateFileExists(stateFileName)
284	
285		if !inProgress && !hasState {
286			return fmt.Errorf("no rebase in progress\n   Start one with: wt rebase")
287		}
288	
289		if inProgress {
290			if err := git.RebaseAbort(); err != nil {
291				return fmt.Errorf("failed to abort rebase: %w", err)
292			}
293		}
294	
295		if hasState {
296			didStash, _ := parseRebaseState()
297			restoreStash(didStash)
298			git.RemoveStateFile(stateFileName)
299		}
300	
301		ui.Success("Rebase aborted")
302		return nil
303	}
