305	func rebaseAll(ctx *cmdContext) error {
306		worktrees, err := git.ListWorktrees()
307		if err != nil {
308			return err
309		}
310	
311		fmt.Println("Rebasing all worktrees onto", ctx.Config.BaseBranch+"…")
312		fmt.Println()
313	
314		spin := ui.NewSpinner(fmt.Sprintf("Fetching %s", ctx.baseRef()))
315		if err := git.Fetch(ctx.Config.Remote, ctx.Config.BaseBranch); err != nil {
316			spin.Stop()
317			ui.Warn("Fetch failed: %v", err)
318		} else {
319			spin.Stop()
320		}
321		fmt.Println()
322	
323		var rebased, skipped, uptodate, failed int
324		var conflicted []string
325		commits := func(n int) string {
326			if n == 1 {
327				return "1 commit"
328			}
329			return fmt.Sprintf("%d commits", n)
330		}
331	
332		for _, wt := range worktrees {
333			branch, _ := git.CurrentBranchIn(wt.Path)
334			if ctx.isBaseBranch(branch) {
335				short := ctx.shortName(wt.Path)
336				fmt.Printf("  %-25s ", short)
337				remoteRef := ctx.Config.Remote + "/" + ctx.Config.BaseBranch
338				ab, err := git.GetAheadBehindIn(wt.Path, remoteRef)
339				if err != nil || ab.Behind == 0 {
340					fmt.Printf("%s\n", ui.Green("✓ up to date"))
341					uptodate++
342				} else {
343					preRef, _ := git.RevParseHeadIn(wt.Path)
344					if err := git.MergeFFIn(wt.Path, remoteRef); err != nil {
345						fmt.Printf("%s\n", ui.Red("✗ fast-forward failed"))
346						failed++
347					} else {
348						msg := fmt.Sprintf("✓ fast-forwarded (%s)", commits(ab.Behind))
349						suffix := lockfileChangedSuffix(wt.Path, preRef)
350						fmt.Printf("%s%s\n", ui.Green(msg), suffix)
351						rebased++
352					}
353				}
354				continue
355			}
356	
357			short := ctx.shortName(wt.Path)
358			fmt.Printf("  %-25s ", short)
359	
360			if git.HasChangesIn(wt.Path) {
361				fmt.Printf("%s\n", ui.Yellow("⚠ has uncommitted changes (skipped)"))
362				skipped++
363				continue
364			}
365	
366			ab, err := git.GetAheadBehindIn(wt.Path, ctx.baseRef())
367			if err != nil || ab.Behind == 0 {
368				fmt.Printf("%s\n", ui.Green("✓ up to date"))
369				uptodate++
370				continue
371			}
372	
373			preRef, _ := git.RevParseHeadIn(wt.Path)
374			if err := git.RebaseIn(wt.Path, ctx.baseRef()); err != nil {
375				git.RebaseAbortIn(wt.Path)
376				fmt.Printf("%s\n", ui.Red("✗ conflicts (aborted)"))
377				conflicted = append(conflicted, short)
378				failed++
379			} else {
380				msg := fmt.Sprintf("✓ rebased (%s from %s)", commits(ab.Behind), ctx.Config.BaseBranch)
381				suffix := lockfileChangedSuffix(wt.Path, preRef)
382				fmt.Printf("%s%s\n", ui.Green(msg), suffix)
383				rebased++
384			}
385		}
386	
387		fmt.Println()
388		fmt.Println("Summary:")
389		if rebased > 0 {
390			fmt.Printf("  %s\n", ui.Green(fmt.Sprintf("✓ %d rebased", rebased)))
391		}
392		if uptodate > 0 {
393			fmt.Printf("  ✓ %d already up to date\n", uptodate)
394		}
395		if skipped > 0 {
396			fmt.Printf("  %s\n", ui.Yellow(fmt.Sprintf("⚠ %d skipped (uncommitted changes)", skipped)))
397		}
398		if failed > 0 {
399			fmt.Printf("  %s\n", ui.Red(fmt.Sprintf("✗ %d failed", failed)))
400		}
401		if len(conflicted) > 0 {
402			fmt.Println()
403			fmt.Println("Resolve conflicts one worktree at a time:")
404			var ctas []string
405			for _, name := range conflicted {
406				cmd := "wt switch " + name + " && wt rebase"
407				fmt.Printf("  %s\n", ui.Cyan(cmd))
408				ctas = append(ctas, cmd)
409			}
410			ui.PrintCTA(ctas...)
411		}
412		if failed > 0 {
413			return errSilent // scripts must see that not every worktree was rebased
414		}
415		return nil
416	}
