418	// parseRebaseState reads the state file and returns whether changes were stashed
419	// and the pre-rebase HEAD ref. Format: "stash_state:pre_ref" (e.g., "stashed:abc123").
420	// Backwards-compatible with old format that had no colon.
421	func parseRebaseState() (didStash bool, preRef string) {
422		state, _ := git.ReadStateFile(stateFileName)
423		parts := strings.SplitN(state, ":", 2)
424		didStash = parts[0] == "stashed"
425		if len(parts) == 2 {
426			preRef = parts[1]
427		}
428		return
429	}
