431	func restoreStash(didStash bool) {
432		if didStash {
433			fmt.Println("Restoring stashed changes…")
434			if err := git.StashPop(); err != nil {
435				ui.Warn("Failed to restore stash — run 'git stash pop' manually")
436			}
437		}
438	}
