440	// lockfileChangedSuffix checks if a lockfile changed in a worktree between
441	// preRef and HEAD. Returns a warning suffix string, or "" if unchanged.
442	func lockfileChangedSuffix(dir, preRef string) string {
443		if preRef == "" {
444			return ""
445		}
446		lockfile, _ := detectInstallCommand(dir)
447		if lockfile == "" {
448			return ""
449		}
450		changed, err := git.DiffNameOnlyIn(dir, preRef, "HEAD")
451		if err != nil {
452			return ""
453		}
454		if slices.Contains(changed, lockfile) {
455			return ui.Yellow(" — lockfile changed, run wt init")
456		}
457		return ""
458	}
459	
460	// autoInstallIfNeeded checks if a lockfile changed between preRef and HEAD,
461	// and if so, runs the detected install command. Warns on failure but never
462	// returns an error (the rebase already succeeded).
463	func autoInstallIfNeeded(ctx *cmdContext, preRef string) {
464		if !ctx.Config.EffectiveAutoInstall() {
465			return
466		}
467	
468		cwd, err := os.Getwd()
469		if err != nil {
470			return
471		}
472	
473		lockfile, command := detectInstallCommand(cwd)
474		if lockfile == "" {
475			return
476		}
477	
478		changed, err := git.DiffNameOnly(preRef, "HEAD")
479		if err != nil {
480			return
481		}
482	
483		if !slices.Contains(changed, lockfile) {
484			return
485		}
486	
487		fmt.Println()
488		fmt.Printf("Lockfile changed (%s) — running install...\n", lockfile)
489		fmt.Printf("  %s %s\n", ui.Dim("$"), command)
490		if err := runShellString(cwd, command); err != nil {
491			fmt.Println()
492			ui.Warn("Install failed — run manually: %s", command)
493		}
494	}
