 38	// submitJSON is what submit prints with --output json.
 39	type submitJSON struct {
 40		Branch string   `json:"branch"`
 41		Pushed bool     `json:"pushed"`
 42		PR     int      `json:"pr,omitempty"`
 43		CTA    []string `json:"cta,omitempty"`
 44	}
 45	
 46	func runSubmit(cmd *cobra.Command, args []string) error {
 47		if err := startOutput(); err != nil {
 48			return err
 49		}
 50		ctx, err := newContext()
 51		if err != nil {
 52			return err
 53		}
 54	
 55		branch, err := git.CurrentBranch()
 56		if err != nil {
 57			return fmt.Errorf("not in a git repository or detached HEAD\n   Run this from inside a worktree")
 58		}
 59	
 60		if ctx.isBaseBranch(branch) {
 61			return fmt.Errorf("cannot submit the base branch (%s)\n   Switch to a feature worktree, or use git push directly", branch)
 62		}
 63	
 64		// Delegate to rebase first
 65		if err := runRebaseWith(rebaseOpts{
 66			continueRebase: submitContinueFlag,
 67			abort:          submitAbortFlag,
 68		}); err != nil {
 69			return err
 70		}
 71	
 72		// After --abort there is nothing to push. A rebase that stops on
 73		// conflicts returns an error above, so nothing is pushed then either.
 74		if submitAbortFlag {
 75			if jsonOut != nil {
 76				return printJSON(submitJSON{Branch: branch})
 77			}
 78			return nil
 79		}
 80	
 81		expectedUpstream := ctx.Config.Remote + "/" + branch
 82		actualUpstream := git.Upstream()
 83	
 84		// Push
 85		fmt.Println()
 86		head, _ := git.RevParseHead()
 87		remoteHead, _ := git.Run("rev-parse", "--verify", "--quiet", expectedUpstream)
 88		pushed := true
 89		switch {
 90		case actualUpstream == expectedUpstream && head != "" && head == remoteHead:
 91			pushed = false
 92			fmt.Printf("Nothing to push %s %s already matches your branch\n", ui.Dash, expectedUpstream)
 93		case actualUpstream == expectedUpstream:
 94			fmt.Println("Pushing to remote…")
 95			if err := git.PushForceWithLease(); err != nil {
 96				// Likely "stale info": the remote moved since we last fetched.
 97				// After the fetch, a retry overwrites those remote commits.
 98				fmt.Println()
 99				ui.Warn("Push rejected %s the remote branch has commits you haven't fetched", ui.Dash)
100				fmt.Println("  Fetching latest remote state…")
101				if fetchErr := git.Fetch(ctx.Config.Remote, branch); fetchErr != nil {
102					return fmt.Errorf("failed to fetch: %w", fetchErr)
103				}
104				if ok, err := ui.ConfirmDiscard("Overwrite the remote commits?", false); !ok {
105					if err != nil {
106						return fmt.Errorf("push rejected: %s has commits you don't have\n   Check them with: git log HEAD..%s", expectedUpstream, expectedUpstream)
107					}
108					return fmt.Errorf("push cancelled")
109				}
110				fmt.Println()
111				fmt.Println("Pushing to remote…")
112				if err := git.PushForceWithLease(); err != nil {
113					return fmt.Errorf("failed to push to remote: %w", err)
114				}
115			}
116		default:
117			fmt.Println("Pushing to remote…")
118			if actualUpstream != "" {
119				fmt.Printf("(fixing upstream: %s → %s)\n", actualUpstream, expectedUpstream)
120			} else {
121				fmt.Println("(setting upstream for new branch)")
122			}
123			if err := git.PushSetUpstream(ctx.Config.Remote); err != nil {
124				return fmt.Errorf("failed to push to remote: %w", err)
125			}
126		}
127		if pushed {
128			fmt.Println()
129			ui.Success("Submitted!")
130		}
131	
132		if git.HasChanges() {
133			fmt.Println("Note: uncommitted changes stay local. Commit them to include them.")
134		}
135	
136		if jsonOut != nil {
137			out := submitJSON{Branch: branch, Pushed: pushed}
138			if pr, err := github.GetPRForBranch(branch); err == nil && github.IsAvailable() {
139				out.CTA = []string{"gh pr create"}
140				if pr != nil {
141					out.PR, out.CTA = pr.Number, []string{"wt watch"}
142				}
143			}
144			return printJSON(out)
145		}
146	
147		if !github.IsAvailable() {
148			return nil
149		}
150		pr, err := github.GetPRForBranch(branch)
151		switch {
152		case err != nil:
153			// No PR info (e.g. not a GitHub remote); say nothing.
154		case pr == nil:
155			fmt.Println()
156			fmt.Printf("No open PR for this branch. Create one: %s\n", ui.Cyan("gh pr create"))
157			ui.PrintCTA("gh pr create")
158		case ui.IsTTY():
159			fmt.Println()
160			if ui.Confirm("Watch PR status?", true) {
161				fmt.Println()
162				return runWatch(cmd, nil)
163			}
164		default:
165			ui.PrintCTA("wt watch")
166		}
167		return nil
168	}

