 49	// isAllDigits reports whether s is non-empty and contains only ASCII digits.
 50	func isAllDigits(s string) bool {
 51		if s == "" {
 52			return false
 53		}
 54		for _, c := range s {
 55			if c < '0' || c > '9' {
 56				return false
 57			}
 58		}
 59		return true
 60	}
 61	
 62	// watchResult describes why the watch loop ended.
 63	type watchResult struct {
 64		success bool
 65		message string
 66	}
 67	
 68	func runWatch(cmd *cobra.Command, args []string) error {
 69		if !github.IsAvailable() {
 70			return fmt.Errorf("gh CLI is required for this command (brew install gh)")
 71		}
 72	
 73		ctx, err := newContext()
 74		if err != nil {
 75			return err
 76		}
 77	
 78		// Resolve what to watch: PR number, worktree name, or current branch
 79		var ref string
 80		if len(args) > 0 {
 81			if isAllDigits(args[0]) {
 82				// PR number — use directly
 83				ref = args[0]
 84			} else {
 85				// Fuzzy-match against worktrees
 86				worktrees, err := git.ListWorktrees()
 87				if err != nil {
 88					return err
 89				}
 90				target, _, resolveErr := resolveWorktree(ctx, worktrees, args[0])
 91				if resolveErr != nil {
 92					return resolveErr
 93				}
 94				if target == "" {
 95					return fmt.Errorf("worktree not found: %s\n   Run wt list to see available worktrees", args[0])
 96				}
 97				branch, err := git.CurrentBranchIn(target)
 98				if err != nil {
 99					return fmt.Errorf("could not determine branch for worktree: %s", args[0])
100				}
101				ref = branch
102			}
103		} else {
104			branch, err := git.CurrentBranch()
105			if err != nil {
106				return fmt.Errorf("not in a git repository or detached HEAD\n   Run this from inside a worktree")
107			}
108	
109			if ctx.isBaseBranch(branch) {
110				return fmt.Errorf("can't watch the base branch (%s) %s it has no associated PR\n   Switch to a feature worktree first", branch, ui.Dash)
111			}
112			ref = branch
113		}
114	
115		// Initial fetch to verify PR exists
116		ws, err := github.GetWatchStatus(ref)
117		if err != nil {
118			return fmt.Errorf("could not fetch PR status for %s: %w", ref, err)
119		}
120		cacheWatchStatus(ws)
121	
122		// Resolve merge method once up front (2 gh calls — no need to repeat per poll)
123		mergeMethod := ""
124		if watchMergeFlag {
125			m, err := github.GetDefaultMergeMethod()
126			if err != nil {
127				ui.Warn("Could not determine merge method, defaulting to merge: %v", err)
128				m = "merge"
129			}
130			mergeMethod = m
131		}
132	
133		// Print header (once)
134		printWatchHeader(ws)
135	
136		// Check if already resolved
137		if res := checkResolved(ws); res != nil {
138			renderWatchTable(ws)
139			printWatchVerdict(ws)
140			if err := mergeIfRequested(ws, mergeMethod); err != nil {
141				return err
142			}
143			printWatchCTA(ws)
144			if res.success {
145				return nil
146			}
147			return errSilent
148		}
149	
150		// Set up Ctrl+C handler
151		sigCh := make(chan os.Signal, 1)
152		signal.Notify(sigCh, os.Interrupt)
153		defer signal.Stop(sigCh)
154	
155		// Poll loop
156		ticker := time.NewTicker(15 * time.Second)
157		defer ticker.Stop()
158	
159		tableLines := renderWatchTable(ws)
160		spin := ui.NewSpinnerRich(buildSpinnerMessage(ws))
161	
162		for {
163			select {
164			case <-sigCh:
165				spin.Stop()
166				fmt.Println()
167				return nil
168	
169			case <-ticker.C:
170				ws, err = github.GetWatchStatus(ref)
171				if err != nil {
172					spin.Stop()
173					return fmt.Errorf("failed to fetch PR status: %w", err)
174				}
175				cacheWatchStatus(ws)
176	
177				// Clear and redraw
178				spin.Stop()
179				ui.ClearLines(tableLines)
180	
181				if res := checkResolved(ws); res != nil {
182					renderWatchTable(ws)
183					printWatchVerdict(ws)
184					if err := mergeIfRequested(ws, mergeMethod); err != nil {
185						return err
186					}
187					printWatchCTA(ws)
188					sendNotification(ws)
189					if res.success {
190						return nil
191					}
192					return errSilent
193				}
194	
195				tableLines = renderWatchTable(ws)
196				spin = ui.NewSpinnerRich(buildSpinnerMessage(ws))
197			}
198		}
199	}
