201	// checkResolved returns a result if the PR has reached a terminal state, or nil to keep polling.
202	func checkResolved(ws *github.WatchStatus) *watchResult {
203		// Already merged
204		if ws.State == "MERGED" {
205			return &watchResult{success: true, message: "Already merged"}
206		}
207	
208		// Closed without merge
209		if ws.State == "CLOSED" {
210			return &watchResult{success: false, message: "PR was closed"}
211		}
212	
213		// Draft PR — always terminal, but verdict prints all concurrent issues
214		if ws.MergeStateStatus == "DRAFT" {
215			return &watchResult{success: false, message: "PR is a draft " + ui.Dash + " mark as ready first"}
216		}
217	
218		// Ready to merge
219		if ws.MergeStateStatus == "CLEAN" {
220			return &watchResult{success: true, message: "Ready to merge"}
221		}
222	
223		// Merge conflict
224		if ws.Mergeable == "CONFLICTING" {
225			return &watchResult{success: false, message: "Merge conflict " + ui.Dash + " run wt rebase"}
226		}
227	
228		// Changes requested
229		if ws.ReviewDecision == "CHANGES_REQUESTED" {
230			return &watchResult{success: false, message: "Changes requested"}
231		}
232	
233		// All CI resolved with failures
234		cs := ws.GetCISummary()
235		if cs.Total > 0 && cs.Pending == 0 && cs.Fail > 0 {
236			return &watchResult{
237				success: false,
238				message: fmt.Sprintf("%d check(s) failed", cs.Fail),
239			}
240		}
241	
242		// All CI resolved, all passed, but still BLOCKED (branch protection rules)
243		if cs.Total > 0 && cs.Pending == 0 && cs.Fail == 0 && ws.MergeStateStatus == "BLOCKED" {
244			return &watchResult{success: false, message: "Blocked by branch protection"}
245		}
246	
247		return nil
248	}
