263	// renderWatchTable prints the CI and Review sections and returns the number of lines printed.
264	func renderWatchTable(ws *github.WatchStatus) int {
265		lines := 0
266	
267		// CI section
268		pass, fail, pending := ws.ChecksByStatus()
269		total := len(pass) + len(fail) + len(pending)
270		if total > 0 {
271			fmt.Println()
272			lines++
273	
274			fmt.Printf("  %s  %s\n", ui.Bold("CI"), ui.Dim(fmt.Sprintf("%d/%d", len(pass), total)))
275			lines++
276	
277			// Build sorted list: pass, fail, pending
278			type checkEntry struct {
279				glyph string
280				name  string
281			}
282			var entries []checkEntry
283			for _, c := range pass {
284				entries = append(entries, checkEntry{glyph: ui.Green(ui.Pass), name: c.Name})
285			}
286			for _, c := range fail {
287				entries = append(entries, checkEntry{glyph: ui.Red(ui.Fail), name: c.Name})
288			}
289			for _, c := range pending {
290				entries = append(entries, checkEntry{glyph: ui.Yellow(ui.Pending), name: c.Name})
291			}
292	
293			// Render in two columns
294			for i := 0; i < len(entries); i += 2 {
295				left := entries[i]
296				leftName := ui.Truncate(left.name, watchCheckColWidth)
297				if i+1 < len(entries) {
298					right := entries[i+1]
299					rightName := ui.Truncate(right.name, watchCheckColWidth)
300					fmt.Printf("    %s  %-*s  %s  %s\n", left.glyph, watchCheckColWidth, leftName, right.glyph, rightName)
301				} else {
302					fmt.Printf("    %s  %s\n", left.glyph, leftName)
303				}
304				lines++
305			}
306		}
307	
308		// Review section
309		items := ws.ReviewItems()
310		showReview := len(items) > 0 || ws.ReviewDecision == "REVIEW_REQUIRED"
311		if showReview {
312			fmt.Println()
313			lines++
314	
315			fmt.Printf("  %s\n", ui.Bold("Review"))
316			lines++
317	
318			if len(items) == 0 {
319				fmt.Printf("    %s  %s\n", ui.Blue(ui.Pending), ui.Dim("review required"))
320				lines++
321			} else {
322				for i := 0; i < len(items); i += 2 {
323					lg, lt := formatReviewItem(items[i])
324					if i+1 < len(items) {
325						rg, rt := formatReviewItem(items[i+1])
326						fmt.Printf("    %s  %-*s  %s  %s\n", lg, watchCheckColWidth, lt, rg, rt)
327					} else {
328						fmt.Printf("    %s  %s\n", lg, lt)
329					}
330					lines++
331				}
332			}
333		}
334	
335		fmt.Println()
336		lines++
337		return lines
338	}
