340	// formatReviewItem returns the glyph and text for a review item separately,
341	// so the caller can pad the text correctly (ANSI codes break %-*s alignment).
342	func formatReviewItem(item github.ReviewItem) (glyph, text string) {
343		login := ui.Truncate(item.Login, 16)
344		switch item.State {
345		case "approved":
346			return ui.Green(ui.Pass), login + "  " + ui.Dim("approved")
347		case "changes_requested":
348			return ui.Red(ui.Fail), login + "  " + ui.Dim("changes")
349		default:
350			return ui.Blue(ui.Pending), login + "  " + ui.Dim("pending")
351		}
352	}
353	
354	// buildSpinnerMessage creates a concise status message for the spinner line.
355	func buildSpinnerMessage(ws *github.WatchStatus) string {
356		cs := ws.GetCISummary()
357	
358		ciWaiting := cs.Pending > 0 || cs.Total == 0
359		reviewWaiting := ws.ReviewDecision == "REVIEW_REQUIRED"
360	
361		switch {
362		case cs.Total == 0 && ws.MergeStateStatus == "BLOCKED":
363			// Typical for fork PRs whose workflows wait for a maintainer to approve them.
364			return ui.Dim("Blocked, no checks have started " + ui.Dash + " workflows may need maintainer approval…")
365		case ciWaiting && reviewWaiting:
366			return ui.Dim("Waiting for checks and review…")
367		case ciWaiting:
368			if cs.Total > 0 {
369				noun := "checks"
370				if cs.Pending == 1 {
371					noun = "check"
372				}
373				return ui.Dim(fmt.Sprintf("Waiting for %d %s…", cs.Pending, noun))
374			}
375			return ui.Dim("Waiting for status…")
376		case reviewWaiting:
377			return ui.Dim("Waiting for review…")
378		default:
379			return ui.Dim("Waiting for status…")
380		}
381	}
