383	// printWatchVerdict outputs the final success/error line after resolution.
384	func printWatchVerdict(ws *github.WatchStatus) {
385		cs := ws.GetCISummary()
386	
387		// Terminal bell
388		fmt.Print("\a")
389	
390		// Draft PRs: show all concurrent issues so the user sees everything to fix
391		if ws.MergeStateStatus == "DRAFT" {
392			if ws.Mergeable == "CONFLICTING" {
393				ui.Error("Merge conflict %s run wt rebase", ui.Dash)
394			}
395			if ws.ReviewDecision == "CHANGES_REQUESTED" {
396				ui.Error("Changes requested")
397			}
398			if cs.Fail > 0 {
399				ui.Error("%d check(s) failed", cs.Fail)
400			}
401			ui.Error("PR is a draft %s mark as ready first", ui.Dash)
402			return
403		}
404	
405		switch {
406		case ws.State == "MERGED":
407			ui.Success("Already merged")
408		case ws.State == "CLOSED":
409			ui.Error("PR was closed")
410		case ws.MergeStateStatus == "CLEAN":
411			ui.Success("Ready to merge")
412		case ws.Mergeable == "CONFLICTING":
413			ui.Error("Merge conflict %s run wt rebase", ui.Dash)
414		case ws.ReviewDecision == "CHANGES_REQUESTED":
415			ui.Error("Changes requested")
416		case cs.Fail > 0:
417			ui.Error("%d check(s) failed", cs.Fail)
418		case ws.MergeStateStatus == "BLOCKED":
419			ui.Error("Blocked by branch protection")
420		}
421	}
