423	// mergeIfRequested merges the PR when --merge is set and the PR is CLEAN.
424	// method is the merge strategy resolved once before the poll loop.
425	func mergeIfRequested(ws *github.WatchStatus, method string) error {
426		if !watchMergeFlag || ws.MergeStateStatus != "CLEAN" {
427			return nil
428		}
429		fmt.Printf("\nMerging PR #%d (%s)...\n", ws.Number, method)
430		if err := github.MergePR(ws.Number, method); err != nil {
431			return fmt.Errorf("merge failed: %w", err)
432		}
433		fmt.Println()
434		ui.Success("Merged PR #%d", ws.Number)
435		ui.PrintCTA("wt close")
436		return nil
437	}
