439	// printWatchCTA emits agent call-to-action hints based on the terminal PR state.
440	func printWatchCTA(ws *github.WatchStatus) {
441		switch {
442		case ws.State == "MERGED", ws.State == "CLOSED":
443			ui.PrintCTA("wt close")
444		case ws.MergeStateStatus == "CLEAN" && !watchMergeFlag:
445			ui.PrintCTA("wt open")
446		case ws.Mergeable == "CONFLICTING":
447			ui.PrintCTA("wt rebase")
448		}
449	}
