451	// sendNotification sends a desktop notification on macOS.
452	func sendNotification(ws *github.WatchStatus) {
453		if runtime.GOOS != "darwin" {
454			return
455		}
456	
457		title := fmt.Sprintf("PR #%d", ws.Number)
458		var message string
459		switch {
460		case ws.State == "MERGED":
461			message = "Already merged"
462		case ws.State == "CLOSED":
463			message = "PR was closed"
464		case ws.MergeStateStatus == "CLEAN":
465			message = "Ready to merge"
466		case ws.Mergeable == "CONFLICTING":
467			message = "Merge conflict"
468		case ws.ReviewDecision == "CHANGES_REQUESTED":
469			message = "Changes requested"
470		default:
471			cs := ws.GetCISummary()
472			if cs.Fail > 0 {
473				message = fmt.Sprintf("%d check(s) failed", cs.Fail)
474			} else {
475				message = "Status resolved"
476			}
477		}
478	
479		_ = exec.Command("osascript", "-e",
480			"on run {t, m}\ndisplay notification m with title t\nend run",
481			title, message).Run()
482	}
