 50	// cachedPR is the open PR for a branch, as wt prompt shows it.
 51	type cachedPR struct {
 52		Number int    `json:"number"`
 53		CI     string `json:"ci,omitempty"` // pass, fail, pending, or "" for no checks
 54	}
 55	
 56	// prCache maps main worktree path → branch → open PR.
 57	type prCache map[string]map[string]cachedPR
 58	
 59	// promptSegment builds the prompt text, or "" when there is nothing to show.
 60	// It runs two git commands and reads two small files, nothing more.
 61	func promptSegment() string {
 62		out, err := git.Run("rev-parse", "--path-format=absolute", "--show-toplevel", "--git-common-dir", "--abbrev-ref", "HEAD")
 63		lines := strings.Split(out, "\n")
 64		if err != nil || len(lines) != 3 {
 65			return ""
 66		}
 67		top, branch := lines[0], lines[2]
 68		main := filepath.Dir(lines[1])
 69		if top == main {
 70			return ""
 71		}
 72	
 73		repo := filepath.Base(main)
 74		cfg, err := config.Load(main, repo)
 75		if err != nil {
 76			return ""
 77		}
 78		ctx := &cmdContext{Config: cfg, RepoName: repo, MainWorktree: main, ParentDir: filepath.Dir(main)}
 79	
 80		var ahead, behind int
 81		if counts, err := git.Run("rev-list", "--left-right", "--count", "HEAD..."+ctx.baseRef()); err == nil {
 82			if a, b, ok := strings.Cut(counts, "\t"); ok {
 83				ahead, _ = strconv.Atoi(a)
 84				behind, _ = strconv.Atoi(b)
 85			}
 86		}
 87		return formatPrompt(ctx.shortName(top), ahead, behind, readPRCache()[main][branch])
 88	}
 89	
 90	func formatPrompt(name string, ahead, behind int, pr cachedPR) string {
 91		parts := []string{name}
 92		if ahead > 0 {
 93			parts = append(parts, fmt.Sprintf("%s%d", ui.ArrowUp, ahead))
 94		}
 95		if behind > 0 {
 96			parts = append(parts, fmt.Sprintf("%s%d", ui.ArrowDown, behind))
 97		}
 98		if pr.Number > 0 {
 99			parts = append(parts, fmt.Sprintf("#%d", pr.Number))
100			switch pr.CI {
101			case "pass":
102				parts = append(parts, ui.Pass)
103			case "fail":
104				parts = append(parts, ui.Fail)
105			case "pending":
106				parts = append(parts, ui.Pending)
107			}
108		}
109		return strings.Join(parts, " ")
110	}
