112	func ciState(cs github.CISummary) string {
113		switch {
114		case cs.Fail > 0:
115			return "fail"
116		case cs.Pending > 0:
117			return "pending"
118		case cs.Pass > 0:
119			return "pass"
120		}
121		return ""
122	}
